/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    CHRONO_KNOT_1, CHRONO_KNOT_2, CHRONO_KNOT_3, CHRONO_SLOW_COEFF, CHRONO_SLOW_MID, CHRONO_SLOW_HIGH, chronoFieldSizeFactor, chronoSlowStrength (+3 more)
 * depends    —
 * used by    src/calculators/specs.generated, src/mechanics/combat/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Chrono Field: how its size and slow strength follow from its level, on the curve the game uses.
 */
export const CHRONO_KNOT_1 = 4 / 11
export const CHRONO_KNOT_2 = 8 / 11
export const CHRONO_KNOT_3 = 10 / 11
export const CHRONO_SLOW_COEFF = 7.5625
export const CHRONO_SLOW_MID = 0.75
export const CHRONO_SLOW_HIGH = 0.9375

export function chronoFieldSizeFactor(maxDistance: number): number {
  if (maxDistance < 1) return (maxDistance / 3) * 0.5
  return ((maxDistance / 3) + 2) * 0.5
}

export function chronoSlowStrength(x: number): number {
  const v = Math.max(0, Math.min(1, x))
  if (v < CHRONO_KNOT_1) return CHRONO_SLOW_COEFF * v * v
  if (v < CHRONO_KNOT_2) return CHRONO_SLOW_MID
  if (v < CHRONO_KNOT_3) return CHRONO_SLOW_HIGH
  const t = v - CHRONO_KNOT_3
  return Math.min(1, CHRONO_SLOW_COEFF * t * t + CHRONO_SLOW_HIGH)
}

/** Effective enemy speed multiplier inside chrono field. */
export function chronoFieldSpeedMultiplier(reductionInput: number): number {
  const x = Math.max(0, Math.min(1, reductionInput))
  if (x <= 0.5) {
    const mapped = 1 - 2 * x
    return (1 - chronoSlowStrength(mapped)) * 0.5
  }
  return 1 - chronoSlowStrength(x)
}

export function chronoFieldDamageTakenMultiplier(lab54Mult: number): number {
  return lab54Mult
}

/**
 * Chrono Loop's measured radial slow and angular motion are distinct effects.
 * The displayed rotation percentage is radians per TWO seconds, not radial slow.
 * Primary controlled-footage measurements, reproduced by the community wiki:
 * https://www.reddit.com/r/TheTowerGame/comments/1jvx8sh/chrono_field_fully_unraveled_with_never_before/
 * Empirical reference model; not a new APK extraction or per-enemy immunity rule.
 * @throws RangeError for an unlocked level outside the measured 0..13 table.
 */
export function chronoLoopMotion(input: { unlocked: boolean; level: number }): {
  radialSpeedMultiplier: number; hiddenSlowFraction: number; rotationRadiansPerSecond: number
} {
  if (!input.unlocked) return { radialSpeedMultiplier: 1, hiddenSlowFraction: 0, rotationRadiansPerSecond: 0 }
  const slow = [0.025, 0.05, 0.1, 0.15, 0.2, 0.25, 0.3, 0.35, 0.4, 0.45, 0.5, 0.55, 0.6, 0.65]
  if (!Number.isInteger(input.level) || input.level < 0 || input.level >= slow.length)
    throw new RangeError('Chrono Loop level must be within the measured 0..13 table')
  const hiddenSlowFraction = slow[input.level]!
  return { radialSpeedMultiplier: 1 - hiddenSlowFraction, hiddenSlowFraction,
    rotationRadiansPerSecond: (0.1 + 0.05 * input.level) / 2 }
}
